    if (codegenContracts.size !== 1) {
        throw generateError("dejavu.generate.codegen-contract-mismatch", `codegen reported mixed catalog contracts: ${[...codegenContracts].sort().join(", ")}`, undefined, "compile");
    }
    const codegenContract = [...codegenContracts][0] ?? "";
